<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ManagementDashboardController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$pid=$p->id;$today=now()->toDateString();
 $planned=DB::table('teaching_load_plans')->where('academic_period_id',$pid)->sum('hours_total');$held=DB::table('lesson_occurrences')->where('academic_period_id',$pid)->where('lesson_date','<=',$today)->whereNotIn('status',['cancelled'])->count();$cancelled=DB::table('lesson_occurrences')->where('academic_period_id',$pid)->where('status','cancelled')->count();$changed=DB::table('lesson_occurrences')->where('academic_period_id',$pid)->whereNotNull('change_note')->count();
 $topicMissing=DB::table('lesson_occurrences')->where('academic_period_id',$pid)->where('lesson_date','<',$today)->where(fn($q)=>$q->whereNull('topic')->orWhere('topic',''))->whereNotIn('status',['cancelled'])->count();
 $journalMissing=DB::table('lesson_occurrences as l')->leftJoin('attendance_records as a','a.lesson_occurrence_id','=','l.id')->where('l.academic_period_id',$pid)->where('l.lesson_date','<',$today)->whereNotIn('l.status',['cancelled'])->groupBy('l.id')->havingRaw('COUNT(a.id)=0')->get()->count();
 $loads=DB::table('teaching_load_plans as p')->leftJoin('teachers as t','t.id','=','p.teacher_id')->leftJoin('subjects as s','s.id','=','p.subject_id')->leftJoin('study_groups as g','g.id','=','p.study_group_id')->where('p.academic_period_id',$pid)->select('p.*','t.last_name','t.first_name','s.name as subject_name','g.name as group_name')->orderBy('t.last_name')->get();foreach($loads as $x){$x->fact=DB::table('lesson_occurrences')->where('academic_period_id',$pid)->where('teacher_id',$x->teacher_id)->where('subject_id',$x->subject_id)->when($x->study_group_id,fn($q)=>$q->where('study_group_id',$x->study_group_id))->where('lesson_date','<=',$today)->whereNotIn('status',['cancelled'])->count();$x->pct=$x->hours_total?round($x->fact*100/$x->hours_total,1):null;}
 $issues=collect();$late=DB::table('lesson_occurrences as l')->leftJoin('attendance_records as a','a.lesson_occurrence_id','=','l.id')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->leftJoin('subjects as s','s.id','=','l.subject_id')->where('l.academic_period_id',$pid)->where('l.lesson_date','<',$today)->whereNotIn('l.status',['cancelled'])->groupBy('l.id','g.name','s.name','l.lesson_date')->havingRaw('COUNT(a.id)=0')->select('l.id','l.lesson_date','g.name as group_name','s.name as subject_name')->orderBy('l.lesson_date')->limit(20)->get();foreach($late as $x)$issues->push(['level'=>'danger','title'=>'Не заполнен журнал','text'=>$x->lesson_date.' · '.$x->group_name.' · '.$x->subject_name,'url'=>route('journal.lesson',$x->id)]);
 $noTopic=DB::table('lesson_occurrences as l')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->leftJoin('subjects as s','s.id','=','l.subject_id')->where('l.academic_period_id',$pid)->where('l.lesson_date','<',$today)->where(fn($q)=>$q->whereNull('l.topic')->orWhere('l.topic',''))->whereNotIn('l.status',['cancelled'])->select('l.id','l.lesson_date','g.name as group_name','s.name as subject_name')->orderBy('l.lesson_date')->limit(20)->get();foreach($noTopic as $x)$issues->push(['level'=>'warning','title'=>'Нет темы занятия','text'=>$x->lesson_date.' · '.$x->group_name.' · '.$x->subject_name,'url'=>route('journal.lesson',$x->id)]);
 $debts=DB::table('semester_results')->where('academic_period_id',$pid)->whereIn(DB::raw('LOWER(value)'),['2','незачет','незачёт','не зачтено'])->count();$practiceOverdue=DB::table('practice_placements')->where('academic_period_id',$pid)->where('ends_on','<',$today)->whereNotIn('status',['completed','failed'])->count();
 return view('management.index',compact('p','planned','held','cancelled','changed','topicMissing','journalMissing','loads','issues','debts','practiceOverdue'));}
}